ALTER TABLE "Product" ADD COLUMN "publicPriceMode" TEXT NOT NULL DEFAULT 'REFERENCE', ADD COLUMN "commercialRevision" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "configuration" JSONB NOT NULL DEFAULT '{}';
